#include "yacht.h"

#include <array>
#include <numeric>

namespace yacht {

Yacht::Yacht(std::vector<int> dice, std::string category)
    : dice_(std::move(dice)), category_(std::move(category)) {}

int Yacht::score() {
  std::array<int, 7> counts{};
  for (int die : dice_) {
    ++counts[die];
  }

  if (category_ == "Ones") {
    return counts[1];
  }
  if (category_ == "Twos") {
    return counts[2] * 2;
  }
  if (category_ == "Threes") {
    return counts[3] * 3;
  }
  if (category_ == "Fours") {
    return counts[4] * 4;
  }
  if (category_ == "Fives") {
    return counts[5] * 5;
  }
  if (category_ == "Sixes") {
    return counts[6] * 6;
  }

  const int total =
      std::accumulate(dice_.begin(), dice_.end(), 0);

  if (category_ == "Full House") {
    bool has_two = false;
    bool has_three = false;

    for (int count = 1; count <= 6; ++count) {
      has_two = has_two || counts[count] == 2;
      has_three = has_three || counts[count] == 3;
    }

    return has_two && has_three ? total : 0;
  }

  if (category_ == "Four of a Kind") {
    for (int count = 1; count <= 6; ++count) {
      if (counts[count] >= 4) {
        return count * 4;
      }
    }
    return 0;
  }

  if (category_ == "Little Straight") {
    return counts[1] == 1 && counts[2] == 1 && counts[3] == 1 &&
                   counts[4] == 1 && counts[5] == 1
               ? 30
               : 0;
  }

  if (category_ == "Big Straight") {
    return counts[2] == 1 && counts[3] == 1 && counts[4] == 1 &&
                   counts[5] == 1 && counts[6] == 1
               ? 30
               : 0;
  }

  if (category_ == "Choice") {
    return total;
  }

  if (category_ == "Yacht") {
    for (int count = 1; count <= 6; ++count) {
      if (counts[count] == 5) {
        return 50;
      }
    }
  }

  return 0;
}

}  // namespace yacht
